/*!
 * Minimal Markdown renderer.
 *
 * The spec asks for a vendored marked.min.js (MIT) so the UI can call
 * `marked.parseInline` on outline node text and `marked.parse` on the wrap-up's
 * exports. Vendoring the real library would add an offline build step, so this
 * file exposes the same two entry points over the subset those two jobs need:
 *
 *   parseInline — escaping, code spans, bold, italics, strikethrough, links.
 *   parse       — the above plus headings, nested lists, blockquotes, fenced
 *                 code, horizontal rules and paragraphs with soft breaks.
 *
 * Drop in the real marked.min.js and the UI keeps working unchanged.
 */
(function (global) {
  "use strict";

  var MARK = "\u0001";

  function escapeHtml(s) {
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function parseInline(src) {
    if (src === null || src === undefined) return "";
    var out = escapeHtml(src);
    var codes = [];
    out = out.replace(/`+([^`]+)`+/g, function (_, code) {
      codes.push(code);
      return MARK + (codes.length - 1) + MARK;
    });
    out = out.replace(/!\[([^\]]*)\]\(([^)\s]+)[^)]*\)/g, "$1");
    out = out.replace(/\[([^\]]*)\]\(([^)\s]+)[^)]*\)/g, function (_, text, href) {
      return '<a href="' + href + '" target="_blank" rel="noreferrer">' + text + "</a>";
    });
    out = out.replace(/(\*\*|__)([\s\S]+?)\1/g, "<strong>$2</strong>");
    out = out.replace(/(?<![\w*_])([*_])(?!\s)([\s\S]+?)(?<!\s)\1(?![\w*_])/g, "<em>$2</em>");
    out = out.replace(/~~([\s\S]+?)~~/g, "<del>$1</del>");
    out = out.replace(new RegExp(MARK + "(\\d+)" + MARK, "g"), function (_, i) {
      return "<code>" + codes[Number(i)] + "</code>";
    });
    return out;
  }

  // --- block level ---------------------------------------------------------

  var HEADING = /^(#{1,6})\s+(.*)$/;
  var RULE = /^\s{0,3}([-*_])(\s*\1){2,}\s*$/;
  var BULLET = /^(\s*)[-*+]\s+(.*)$/;
  var ORDERED = /^(\s*)\d+[.)]\s+(.*)$/;
  var QUOTE = /^\s{0,3}>\s?(.*)$/;
  var FENCE = /^\s*(```|~~~)(.*)$/;

  //: A tab is one level; so is every four spaces. The outline's own nesting is
  //: tabs, the wrap-up's exports are flat, and both have to survive.
  function indentOf(space) {
    var width = 0;
    for (var i = 0; i < space.length; i++) width += space[i] === "\t" ? 4 : 1;
    return Math.floor(width / 2);
  }

  function listItem(line) {
    var m = BULLET.exec(line);
    if (m) return { ordered: false, depth: indentOf(m[1]), text: m[2] };
    m = ORDERED.exec(line);
    if (m) return { ordered: true, depth: indentOf(m[1]), text: m[2] };
    return null;
  }

  /** Consume one list (with its nested sublists) starting at `i`. */
  function renderList(lines, i, depth, out) {
    var first = listItem(lines[i]);
    var tag = first.ordered ? "ol" : "ul";
    out.push("<" + tag + ">");
    while (i < lines.length) {
      var item = listItem(lines[i]);
      if (!item || item.depth < depth) break;
      if (item.depth > depth) {
        // A deeper bullet belongs inside the item that was just opened.
        var inner = [];
        i = renderList(lines, i, item.depth, inner);
        out.push(inner.join(""));
        continue;
      }
      if (item.ordered !== first.ordered) break;
      out.push("<li>" + parseInline(item.text) + "</li>");
      i++;
    }
    out.push("</" + tag + ">");
    return i;
  }

  function parse(src) {
    if (src === null || src === undefined) return "";
    var lines = String(src).replace(/\r\n?/g, "\n").split("\n");
    var out = [];
    var i = 0;
    while (i < lines.length) {
      var line = lines[i];

      if (!line.trim()) {
        i++;
        continue;
      }

      var fence = FENCE.exec(line);
      if (fence) {
        var code = [];
        i++;
        while (i < lines.length && !FENCE.test(lines[i])) code.push(lines[i++]);
        i++; // the closing fence, or the end of the input
        out.push("<pre><code>" + escapeHtml(code.join("\n")) + "</code></pre>");
        continue;
      }

      if (RULE.test(line)) {
        out.push("<hr>");
        i++;
        continue;
      }

      var heading = HEADING.exec(line);
      if (heading) {
        var level = heading[1].length;
        out.push("<h" + level + ">" + parseInline(heading[2]) + "</h" + level + ">");
        i++;
        continue;
      }

      if (QUOTE.test(line)) {
        var quoted = [];
        while (i < lines.length && QUOTE.test(lines[i])) quoted.push(QUOTE.exec(lines[i++])[1]);
        out.push("<blockquote>" + parse(quoted.join("\n")) + "</blockquote>");
        continue;
      }

      if (listItem(line)) {
        i = renderList(lines, i, listItem(line).depth, out);
        continue;
      }

      // A paragraph runs to the next blank line or block opener. Its own line
      // breaks are kept: the wrap-up writes one summary sentence per line.
      var para = [];
      while (i < lines.length && lines[i].trim() && !isBlockStart(lines[i])) para.push(lines[i++]);
      out.push("<p>" + para.map(parseInline).join("<br>") + "</p>");
    }
    return out.join("\n");
  }

  function isBlockStart(line) {
    return (
      HEADING.test(line) || RULE.test(line) || QUOTE.test(line) || FENCE.test(line) || !!listItem(line)
    );
  }

  global.marked = { parseInline: parseInline, parse: parse, escapeHtml: escapeHtml };
})(typeof window !== "undefined" ? window : this);
